:root{--bg:#08100f;--panel:#0d1715;--panel2:#101d1a;--panel3:#14231f;--line:#22332e;--muted:#758781;--text:#e7eee9;--soft:#aab8b1;--lime:#c6f36b;--cyan:#62d8c0;--orange:#f0a568;--red:#f07878;--mono:'DM Mono',monospace;--sans:'DM Sans',sans-serif;--display:'Space Grotesk',sans-serif}
*{box-sizing:border-box}
body{margin:0;background:var(--bg);color:var(--text);font-family:var(--sans);font-size:13px}
button{font:inherit;color:inherit;cursor:pointer}
button:focus-visible{outline:2px solid var(--lime);outline-offset:2px}
.app-shell{min-height:100vh;display:flex}
.sidebar{width:242px;flex-shrink:0;background:#0a1210;border-right:1px solid #1b2a25;padding:25px 16px 16px;display:flex;flex-direction:column;min-height:100vh}
.brand{display:flex;align-items:center;gap:11px;text-decoration:none;color:var(--text);padding:0 10px 32px}
.brand-mark{width:33px;height:33px;border:1px solid #557044;border-radius:10px;color:var(--lime);display:grid;place-items:center;font:700 19px var(--display);position:relative}
.brand-mark span{position:absolute;font:11px var(--sans);right:-4px;top:-4px;color:var(--cyan)}
.brand-name{font:600 16px var(--display);letter-spacing:1.9px}
.brand-name small{display:block;color:#718079;font:9px var(--mono);letter-spacing:1.4px;margin-top:3px}
.side-label{color:#64736c;font:10px var(--mono);letter-spacing:1.5px;padding:0 11px 10px}
.nav-list{display:grid;gap:3px}
.nav-item{border:0;background:transparent;color:#9aa9a2;text-align:left;display:flex;align-items:center;gap:12px;padding:11px 12px;border-radius:6px;transition:.18s;font-size:12px}
.nav-item:hover{background:#121f1b;color:var(--text)}
.nav-item.active{color:var(--lime);background:#19251c;box-shadow:inset 2px 0 var(--lime)}
.nav-icon{font-size:17px;width:18px;text-align:center;color:#82948a}
.nav-item.active .nav-icon{color:var(--lime)}
.nav-count,.archive-count{margin-left:auto;font:10px var(--mono);color:#798982}
.nav-dot{margin-left:auto;width:6px;height:6px;border-radius:50%;background:var(--cyan)}
.side-label-spaced{margin-top:30px}
.sidebar-spacer{flex:1;min-height:28px}
.protocol-card{border:1px solid #26362c;background:linear-gradient(145deg,#17241a,#101a17);padding:14px 13px 11px;border-radius:7px;margin:12px 2px 20px}
.protocol-eyebrow{font:9px var(--mono);letter-spacing:.7px;color:var(--lime);display:flex;align-items:center;gap:7px}
.pulse-dot{width:6px;height:6px;background:var(--lime);display:inline-block;border-radius:50%;box-shadow:0 0 10px #c6f37588;animation:pulse 2s infinite}
@keyframes pulse{50%{opacity:.45;box-shadow:0 0 2px #c6f37544}
}
.protocol-title{font:500 14px var(--display);margin-top:13px}
.protocol-card p{color:#87968e;font-size:11px;line-height:1.6;margin:6px 0 15px}
